const MAX_SUGGESTIONS = 8;

interface Suggestion {
  name: string;
  description?: string;
}

export function NavSearch({ initialQuery = "" }: { initialQuery?: string }) {
  const [query, setQuery] = useState(initialQuery);
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const debounceRef = useRef<number>();
  const inputRef = useRef<HTMLInputElement>(null);

  const fetchSuggestions = async (q: string) => {
    if (!q.trim()) {
      setSuggestions([]);
      return;
    }
    try {
      const res = await fetch(
        `/api/tools?q=${encodeURIComponent(q.trim())}&limit=${MAX_SUGGESTIONS}`,
      );
      // Drop responses whose query no longer matches the input (out-of-order
      // resolves or a superseded keystroke) so the dropdown never goes stale.
      if (inputRef.current && inputRef.current.value.trim() !== q.trim())
        return;
      if (!res.ok) {
        setSuggestions([]);
        return;
      }
      const data = await res.json();
      setSuggestions((data.tools || []).slice(0, MAX_SUGGESTIONS));
    } catch (e) {
      console.error("Failed to fetch search suggestions:", e);
      setSuggestions([]);
    }
  };

  const handleInput = (value: string) => {
    setQuery(value);
    setShowSuggestions(true);
    clearTimeout(debounceRef.current);
    debounceRef.current = window.setTimeout(() => fetchSuggestions(value), 300);
  };
  const [chartView, setChartViewState] = useState<ChartView>("30d");
  const [versionTrendsData, setVersionTrendsData] =
    useState<VersionTrendData | null>(null);
  const [versionTrendsLoading, setVersionTrendsLoading] = useState(false);

  // Sync from localStorage on mount (after hydration)
  useEffect(() => {
    const stored = getStoredChartView();
    if (stored !== chartView) {
      setChartViewState(stored);
    }
  }, []);

  const setChartView = (view: ChartView) => {
    setChartViewState(view);
    if (typeof window !== "undefined") {
      localStorage.setItem(CHART_VIEW_KEY, view);
    }
  };

  // Fetch version trends when switching to that tab
  useEffect(() => {
    if (
      chartView === "versions" &&
      !versionTrendsData &&
      !versionTrendsLoading
    ) {
      setVersionTrendsLoading(true);
      fetch(`/api/downloads/${tool}/version-trends?days=30`)
        .then((res) => res.json<VersionTrendData>())
        .then((data) => {
          setVersionTrendsData(data);
          setVersionTrendsLoading(false);
        })
        .catch(() => {
          setVersionTrendsLoading(false);
        });
    }
  }, [chartView, tool, versionTrendsData, versionTrendsLoading]);

  return (
    <div class="download-panel bg-dark-800 border border-dark-600 rounded-lg p-4">
      <h2 class="text-lg font-semibold text-gray-200 mb-3">Downloads</h2>

      <div class="mb-4">
        <div class="flex items-center justify-between mb-2">
"}

