/// <reference path="./astro-worker.d.ts" />

// Custom worker wrapper for Astro's worker bundle.

import astroWorker from "../web/dist/server/entry.mjs";
import { drizzle } from "drizzle-orm/d1";
import { ensureTokenObservabilitySchema } from "./migrations.js";
import { observeTokenPool } from "./token-observability.js";
import {
  dispatchUpdateWorkflow,
  UPDATE_WORKFLOW_CRON,
} from "./workflow-dispatch.js";

const TOKEN_OBSERVABILITY_CRON = "*/15 * * * *";

function isMissingTokenObservabilitySchema(error: unknown): boolean {
  const message = error instanceof Error ? error.message : String(error);
  return message.includes("no such table") && message.includes("token_");
}

async function observeWithSchemaRetry(env: Env): Promise<void> {
  try {
    await observeTokenPool(env);
  } catch (error) {
    if (!isMissingTokenObservabilitySchema(error)) throw error;

    await ensureTokenObservabilitySchema(drizzle(env.DB));
    await observeTokenPool(env);
  }
}

export default {
  fetch: astroWorker.fetch,
  async scheduled(controller, env, ctx) {
    switch (controller.cron) {
      case TOKEN_OBSERVABILITY_CRON:
        ctx.waitUntil(
          observeWithSchemaRetry(env).catch((error: unknown) => {
            console.error("token_observability_failed", {
              error: error instanceof Error ? error.message : String(error),
            });
          }),
        );
        break;
      case UPDATE_WORKFLOW_CRON:
#!/usr/bin/env node
/**
 * Regression tests for the built Astro/Tailwind output.
 *
 * These assume `aube --dir web run build` has already run. CI does that before
 * `aube run test`, which keeps this test focused on verifying the artifact.
 */
import { describe, it } from "node:test";
import assert from "node:assert";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const DIST_CLIENT_DIR = fileURLToPath(
  new URL("../web/dist/client", import.meta.url),
);
const ASTRO_ASSET_DIR = join(DIST_CLIENT_DIR, "_astro");

function readBuiltCss() {
  assert.ok(
    existsSync(ASTRO_ASSET_DIR),
    "web build assets are missing; run `aube --dir web run build` before tests",
  );

  const cssFiles = readdirSync(ASTRO_ASSET_DIR)
    .filter((file) => file.endsWith(".css"))
    .sort();

  assert.ok(cssFiles.length > 0, "web build did not emit a CSS asset");

  return cssFiles
    .map((file) => readFileSync(join(ASTRO_ASSET_DIR, file), "utf8"))
    .join("\n");
}

describe("web build CSS", () => {
  it("includes Tailwind preflight and project utilities", () => {
    const css = readBuiltCss();

    assert.match(
      css,
      /a\{color:inherit;[-a-z:]*text-decoration:inherit/,
      "Tailwind preflight reset is missing",
    );

    const expectedUtilities = [
      ".bg-dark-900{background-color:#0a0a0f}",
      ".bg-dark-800{background-color:#12121a}",
      ".text-neon-purple{color:#b026ff}",
      ".hover\\:text-neon-pink:hover{color:#ff2d95}",
      ".px-4{padding-inline:calc(var(--spacing) * 4)}",
      ".py-8{padding-block:calc(var(--spacing) * 8)}",
      ".text-xl{font-size:var(--text-xl);",
      ".max-w-6xl{max-width:var(--container-6xl)}",
    ];

    for (const utility of expectedUtilities) {
      assert.ok(css.includes(utility), `missing CSS utility: ${utility}`);
    }
  });
});

describe("web build static version files", () => {
  it("includes TOML assets under /data", () => {
    const nodeToml = join(DIST_CLIENT_DIR, "data", "node.toml");

    assert.ok(existsSync(nodeToml), "missing static /data/node.toml asset");

    assert.match(readFileSync(nodeToml, "utf8"), /^\[versions\]/);
  });
});
