CREATE TABLE daily_combined_stats (date TEXT PRIMARY KEY, unique_users INTEGER);
CREATE TABLE daily_mau_stats (date TEXT PRIMARY KEY, mau INTEGER);
CREATE TABLE daily_version_stats (date TEXT PRIMARY KEY, total_requests INTEGER, unique_users INTEGER);
CREATE TABLE version_updates (id INTEGER PRIMARY KEY, date TEXT, tool_id INTEGER, versions_added INTEGER);
CREATE TABLE version_requests (id INTEGER PRIMARY KEY, ip_hash TEXT, created_at INTEGER, day INTEGER);
'''
def lit(v):
 if v is None:return 'NULL'
 if isinstance(v,(list,dict)):v=json.dumps(v)
 if isinstance(v,(int,float)):return str(v)
 return "'"+str(v).replace("'","''")+"'"
def insert(t,d):
 global sql
 sql+=f"INSERT OR REPLACE INTO {t} ({','.join(d)}) VALUES ({','.join(lit(v) for v in d.values())});\n"
d=json.load(open('/tmp/ui-tools.json')); dagger=json.load(open('/tmp/ui-dagger.json'))
tools={t['name']:t for t in d['tools']+dagger['tools']};downs=d['downloads']|dagger['downloads']
now=datetime.date.today();timestamp=now.isoformat()
for i,t in enumerate(tools.values(),1):
 row={k:v for k,v in t.items() if k in cols+['name','version_count']};row['id']=i;insert('tools',row)
 total=downs.get(t['name'],1200);back=t.get('backends',['core:unknown'])[0].split(':')[0]
 insert('tool_download_summaries',dict(tool_id=i,downloads_30d=total,downloads_all_time=total*5,updated_at=timestamp))
 insert('trending_tool_summaries',dict(tool_id=i,downloads_30d=total,daily_boost=10,trending_score=10000-i,sparkline=json.dumps([10,12,8,17,22,16,30]),updated_at=timestamp))
 p=r/'docs'/f"{t['name']}.toml"
 vs=tomllib.loads(p.read_text()).get('versions',{}) if p.exists() else {t['latest_version']:None}
 for j,(version,date) in enumerate(reversed(list(vs.items()))):
  insert('versions',dict(tool_id=i,version=version,created_at=str(date) if date else None,sort_order=j,prerelease=int(any(x in version for x in ['rc','beta','alpha']))))
 for day in range(1,61):
  date=(now-datetime.timedelta(days=day)).isoformat();count=round(total/30*(.75+ .5*(math.sin(day)+1)/2))
  insert('daily_tool_stats',dict(date=date,tool_id=i,downloads=count,unique_users=max(1,count//2)))
  insert('daily_tool_backend_stats',dict(date=date,tool_id=i,backend_type=back,downloads=count))
  insert('daily_tool_version_stats',dict(date=date,tool_id=i,version=t['latest_version'],downloads=count))
  insert('version_updates',dict(id=i*100+day,date=date,tool_id=i,versions_added=1))
 insert('tool_version_download_summaries',dict(tool_id=i,version=t['latest_version'],downloads_all_time=total))
for day in range(1,371):
 date=(now-datetime.timedelta(days=day)).isoformat();mau=round(755000*math.exp(-day*.002));dau=round(mau*.13)
 insert('daily_combined_stats',dict(date=date,unique_users=dau));insert('daily_mau_stats',dict(date=date,mau=mau))
 insert('daily_stats',dict(date=date,total_downloads=dau*4,unique_users=dau))
 for back,factor in [('aqua',.6),('core',.25),('github',.05),('npm',.04),('vfox',.035),('pipx',.025)]:
  insert('daily_backend_stats',dict(date=date,backend_type=back,downloads=round(dau*4*factor),unique_users=round(dau*factor)))
for item in json.load(open('/tmp/ui-mau.json'))['daily']:
 insert('daily_combined_stats',dict(date=item['date'],unique_users=item['dau']));insert('daily_mau_stats',dict(date=item['date'],mau=item['mau']))
for back,count in d['backendCounts'].items():insert('backend_tool_summaries',dict(backend_type=back,tool_count=count,updated_at=timestamp))
