export type SortKey = "name" | "downloads" | "updated";
export interface DirectoryState {
  page: number;
  search: string;
  sort: SortKey;
  backends: string[];
}
export function readDirectoryState(query: string): DirectoryState {
  const params = new URLSearchParams(query);
  const sort = params.get("sort");
  const page = Number(params.get("page"));
  return {
    page: Number.isInteger(page) && page > 0 ? page : 1,
    search: params.get("q") || "",
    sort: sort === "name" || sort === "updated" ? sort : "downloads",
    backends: (params.get("backends") || "").split(",").filter(Boolean),
  };
}
export function directoryQuery(state: Partial<DirectoryState>): string {
  const params = new URLSearchParams();
  if (state.page && state.page > 1) params.set("page", String(state.page));
  if (state.search?.trim()) params.set("q", state.search.trim());
  if (state.sort && state.sort !== "downloads") params.set("sort", state.sort);
  if (state.backends?.length) params.set("backends", state.backends.join(","));
  return params.toString();
}
EOF
cat > web/src/lib/directory-state.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { readDirectoryState, directoryQuery } from "./directory-state";

test("directory links preserve search, sorting, backend selection, and pagination", () => {
  const state = { page: 3, search: "c++ & tools", sort: "updated" as const, backends: ["aqua", "github"] };
  assert.deepEqual(readDirectoryState(directoryQuery(state)), state);
});
test("empty filters return the canonical directory and malformed links use defaults", () => {
  const defaults = { page: 1, search: "", sort: "downloads" as const, backends: [] };
  assert.equal(directoryQuery(defaults), "");
  assert.deepEqual(readDirectoryState("?page=-1&sort=other&backends=,,"), defaults);
  assert.equal(readDirectoryState("?page=1.5").page, 1);
  assert.equal(readDirectoryState("?page=garbage").page, 1);
});
test("search trims whitespace and encodes slashes, plus signs and ampersands", () => {
  const query = directoryQuery({ search: "  foo/bar+c&d  " });
  assert.equal(readDirectoryState(query).search, "foo/bar+c&d");
  assert.equal(directoryQuery({ search: "  " }), "");
});
