      status: 200,
      headers: {
        "Content-Type": "application/json",
        "Cache-Control": "public, max-age=600, stale-while-revalidate=3600",
      },
    });
  } catch (error) {
    console.error("Get paginated tools error:", error);
    return new Response(JSON.stringify({ error: "Failed to load tools" }), {
