<Layout title="Stats" description="Download statistics and ecosystem metrics for mise">
  <div class="stats-page space-y-8">
    <div class="page-heading">
      <h1>Ecosystem stats</h1>
      {formattedLatestStatsDate && (
        <p class="mt-1 text-sm text-gray-500">Daily analytics through {formattedLatestStatsDate}</p>
      )}
    </div>

    <section class="audience-panel" aria-label="Audience growth">
      {dauMauData ? <MauHistory daily={dauMauData.daily} /> : <div class="inline-notice">Audience history is currently unavailable.</div>}
    </section>
    <div class="section-heading"><h2>Across the ecosystem</h2><span>Tools, backends, and downloads</span></div>
    <!-- Overview cards -->
    <div class="metric-grid grid grid-cols-1 md:grid-cols-4 gap-4">
      <div class="bg-dark-800 border border-dark-600 rounded-lg p-6">
        <div class="text-sm text-gray-400 mb-1">Total Tools</div>
        <div class="text-3xl font-bold text-gray-100">
          {toolsData.tool_count.toLocaleString()}
        </div>
      </div>
      <div class="bg-dark-800 border border-dark-600 rounded-lg p-6">
        <div class="text-sm text-gray-400 mb-1">Backends</div>
        <div class="text-3xl font-bold text-gray-100">
          {sortedCounts.length}
        </div>
      </div>
      <div class="bg-dark-800 border border-dark-600 rounded-lg p-6">
        <div class="text-sm text-gray-400 mb-1">Downloads (30d)</div>
        <div class="flex items-baseline gap-2">
          <span class="text-3xl font-bold text-gray-100">
            {formatCompact(totalDownloads)}
          </span>
          {growthData && growthData.global.mom !== null && (
            <span class={`text-xs ${growthData.global.mom >= 0 ? 'text-green-400' : 'text-red-400'}`}>
              {growthData.global.mom >= 0 ? '↑' : '↓'} {Math.abs(growthData.global.mom).toFixed(1)}%
            </span>
          )}
        </div>
        <div class="text-xs text-gray-500 mt-1">vs prior 30 days</div>
      </div>
      <div class="bg-dark-800 border border-dark-600 rounded-lg p-6">
        <div class="text-sm text-gray-400 mb-1">Downloads (7d)</div>
        <div class="flex items-baseline gap-2">
          <span class="text-3xl font-bold text-gray-100">
            {growthData ? formatCompact(growthData.global.thisWeek) : "..."}
          </span>
          {growthData && growthData.global.wow !== null ? (
            <span class={`text-xs ${growthData.global.wow >= 0 ? 'text-green-400' : 'text-red-400'}`}>
              {growthData.global.wow >= 0 ? '↑' : '↓'} {Math.abs(growthData.global.wow).toFixed(1)}%
            </span>
          ) : null}
        </div>
        <div class="text-xs text-gray-500 mt-1">vs prior 7 days</div>
      </div>
    </div>

    <!-- DAU and Version Updates charts -->
    <div class="grid grid-cols-1 lg:grid-cols-2 gap-4">
      {dauMauData && dauMauData.daily.length > 0 && (
        <div class="bg-dark-800 border border-dark-600 rounded-lg p-4">
          <h2 class="text-lg font-semibold text-gray-200 mb-3">
            Daily Active Users
          </h2>
          <div class="overflow-x-auto">
            {(() => {
              const width = 500;
              const height = 200;
              const padding = { top: 20, right: 50, bottom: 30, left: 50 };
              const chartWidth = width - padding.left - padding.right;
              const chartHeight = height - padding.top - padding.bottom;
              type DayData = { date: string; dau: number };
              const data: DayData[] = dauMauData.daily.slice(-29);
              const maxDAU = Math.max(...data.map(d => d.dau), 1);
              const barWidth = chartWidth / data.length - 2;

              return (
                <svg
                  width={width}
                  height={height}
                  class="min-w-[400px]"
                  role="group"
                  aria-label="Daily active users by date. Use the left and right arrow keys to inspect days."
                  data-daily-chart
                >
                  <text x={padding.left - 10} y={padding.top} text-anchor="end" class="fill-purple-400 text-xs">
                    {formatCompact(maxDAU)}
                  </text>
                  <text x={padding.left - 10} y={padding.top + chartHeight} text-anchor="end" class="fill-purple-400 text-xs">
