---
import observations from '../data/mise-adoption.json';
import { starChange } from '../lib/mise-adoption';
const latest = observations.at(-1)!;
const change = starChange(observations, 30);
const since = new Date(latest.date);
since.setUTCFullYear(since.getUTCFullYear() - 1);
const points = observations.filter(p => p.date >= since.toISOString().slice(0, 10));
const metrics = [
  { label: 'GitHub stars', value: latest.stars.toLocaleString(), note: change === null ? 'jdx/mise' : `${change >= 0 ? '+' : ''}${change.toLocaleString()} over 30 days` },
  { label: 'Homebrew installs', value: latest.brewInstalls?.toLocaleString() ?? '—', note: 'Rolling 30 days · install-on-request' },
  { label: 'Homebrew rank', value: latest.brewRank === null ? '—' : `#${latest.brewRank}`, note: 'Among install-on-request formulae' },
  { label: 'Homebrew share', value: latest.brewPercent === null ? '—' : `${latest.brewPercent}%`, note: 'Share of install-on-request installs' },
];
const charts = [
  { title: 'GitHub stars', key: 'stars' as const, color: 'var(--accent)' },
  { title: 'Homebrew installs · rolling 30 days', key: 'brewInstalls' as const, color: 'var(--data)' },
];
---
<section class="mise-adoption" aria-labelledby="mise-adoption-heading">
  <div class="section-heading"><h2 id="mise-adoption-heading">mise adoption</h2><a href="https://github.com/jdx/mise-analytics">Source: mise-analytics ↗</a></div>
  <p class="adoption-context">GitHub and Homebrew through {latest.date}. Homebrew counts installs of mise itself, including repeat installs—not unique users or tools installed with mise.</p>
  <div class="adoption-metrics">{metrics.map(m => <div><h3>{m.label}</h3><strong>{m.value}</strong><p>{m.note}</p></div>)}</div>
  <div class="adoption-charts">{charts.map(chart => {
    const valid = points.filter(p => p[chart.key] !== null);
    if (!valid.length) return null;
    const max = Math.max(...valid.map(p => p[chart.key]!), 1);
    const firstTime = Date.parse(points[0].date);
    const range = Math.max(Date.parse(latest.date) - firstTime, 1);
    const x = (date: string) => 48 + (Date.parse(date) - firstTime) / range * 464;
    const y = (value: number) => 172 - value / max * 140;
    // Break the line at missing observations instead of interpolating across them.
    let previousTime = 0;
    const path = valid.map(p => {
      const time = Date.parse(p.date);
      const command = time - previousTime === 86_400_000 ? 'L' : 'M';
      previousTime = time;
      return `${command}${x(p.date).toFixed(2)},${y(p[chart.key]!).toFixed(2)}`;
    }).join(' ');
    return <div class="adoption-chart"><h3>{chart.title}</h3>
      <svg viewBox="0 0 540 205" role="img" aria-label={`${chart.title} from ${points[0].date} to ${latest.date}. Latest value ${latest[chart.key]?.toLocaleString() ?? 'unavailable'}. Full daily values are in the source data.`}>
        {[0, 0.5, 1].map(f => <g><line x1="48" x2="512" y1={y(max*f)} y2={y(max*f)} stroke="var(--border)" stroke-dasharray="3 5"/><text x="40" y={y(max*f)+4} text-anchor="end">{Math.round(max*f).toLocaleString('en-US', {notation:'compact'})}</text></g>)}
        <path d={path} fill="none" stroke={chart.color} stroke-width="2.5" stroke-linejoin="round" />
        <text x="48" y="197">{points[0].date}</text><text x="512" y="197" text-anchor="end">{latest.date}</text>
      </svg>
    </div>;
  })}</div>
  <p class="adoption-context"><a href="https://github.com/jdx/mise-analytics/blob/main/mise.csv">Explore the daily data ↗</a> · Refreshed daily from the public repository.</p>
</section>
EOF
