    </div>
  </div>
  <div class="star-chart-scroll">
    <svg viewBox="0 0 1000 265" role="img" aria-label={`GitHub star history for mise and Homebrew. ${projection ? `At current growth rates, mise is projected to pass Homebrew on ${dateLabel(projection.hitDate)}.` : 'No near-term crossover projected.'}`}>
