export function AuthButton() {
  const [state, setState] = useState<AuthState>({
    authenticated: false,
    username: null,
    loading: true,
  });

  useEffect(() => {
    async function checkAuth() {
      try {
        const response = await fetch("/api/auth/me");
        const contentType = response.headers.get("content-type");
        if (!contentType?.includes("application/json")) {
          setState({ authenticated: false, username: null, loading: false });
          return;
        }
        const data = await response.json<AuthStatusResponse>();
        setState({
          authenticated: data.authenticated,
          username: data.username || null,
          loading: false,
        });
      } catch {
        setState({ authenticated: false, username: null, loading: false });
      }
    }

    checkAuth();
  }, []);

  if (state.loading) {
    return (
      <div class="px-3 py-1.5 text-gray-500">
        <span class="animate-pulse">...</span>
      </div>
    );
  }

  // Get current page path for return_to
  const currentPath =
    typeof window !== "undefined" ? window.location.pathname : "/";
  const loginUrl = `/api/auth/login?return_to=${encodeURIComponent(currentPath)}`;
  const logoutUrl = `/api/auth/logout?return_to=${encodeURIComponent(currentPath)}`;

  if (state.authenticated) {
    return (
      <>
        <a
          href={logoutUrl}
          aria-label={`Logout ${state.username || "GitHub user"}`}
          class="text-gray-400 transition-colors hover:text-gray-200 xl:hidden"
        >
          <GitHubIcon />
        </a>
        <div class="hidden items-center gap-3 xl:flex">
          <span class="text-gray-400 text-sm">
            <GitHubIcon />
          </span>
          <span class="text-gray-300">{state.username}</span>
          <a
            href={logoutUrl}
            class="text-gray-500 hover:text-gray-300 text-sm transition-colors"
          >
            Logout
          </a>
        </div>
      </>
    );
  }

  return (
    <a
      href={loginUrl}
      aria-label="Login with GitHub"
      class="flex items-center gap-2 px-2 py-1.5 xl:px-3 bg-dark-700 hover:bg-dark-600 border border-dark-500 rounded-lg text-gray-300 hover:text-white transition-colors"
    >
      <GitHubIcon />
      <span class="hidden xl:inline">Login with GitHub</span>
    </a>
  );
}
