  background: var(--surface);
}
.skip-link:focus {
  top: 10px;
}
.site-header {
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}
.site-nav {
  max-width: 1344px;
  margin: auto;
  min-height: 80px;
  padding: 16px 32px;
  display: flex;
  align-items: center;
  gap: 48px;
}
.wordmark {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 700;
  letter-spacing: -0.03em;
  white-space: nowrap;
}
.brand-symbol {
  background: var(--accent);
  color: var(--canvas);
  width: 34px;
  height: 34px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  font-size: 23px;
}
.wordmark-sub {
  color: var(--muted);
  font-weight: 400;
  letter-spacing: -0.02em;
}
.primary-nav {
  display: flex;
  align-items: center;
  gap: 6px;
}
.primary-nav a {
  padding: 8px 16px;
  font-size: 14px;
  color: var(--muted);
  border-radius: 7px;
}
.primary-nav a[aria-current] {
  color: var(--text);
  background: var(--surface-raised);
  font-weight: 600;
}
.nav-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: 0;
}
.theme-select select {
  max-width: 105px;
  background: transparent;
  color: var(--muted);
  border: 0;
  font-size: 12px;
  padding: 8px 0;
}
.site-menu {
  position: relative;
  font-size: 13px;
}
.site-menu summary {
  list-style: none;
  color: var(--text-secondary);
  display: flex;
  gap: 12px;
  padding: 8px;
}
.site-menu summary::-webkit-details-marker {
  display: none;
}
.site-menu-panel {
  position: absolute;
  right: 0;
  top: calc(100% + 12px);
  min-width: 220px;
  z-index: 60;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px;
  box-shadow: var(--shadow);
  display: grid;
  gap: 12px;
}
.site-menu-panel a {
  display: block;
  padding: 4px;
}
.site-main {
  max-width: 1344px;
  margin: auto;
  padding: 48px 32px 80px;
  min-height: 75vh;
}
.site-footer {
  max-width: 1280px;
  margin: 0 auto;
  border-top: 1px solid var(--border);
  padding: 28px 0 36px;
  display: flex;
.download-panel > h2 {
  font-size: 19px;
  margin-bottom: 20px;
}
.versions-section {
  border-top: 1px solid var(--border);
  padding-top: 28px;
  min-width: 0;
}
.versions-section > h2 {
  font-size: 21px;
  margin-bottom: 22px;
}
.versions-section table {
  font-variant-numeric: tabular-nums;
}
.versions-section td {
  overflow-wrap: anywhere;
}
@media (max-width: 1000px) {
  .site-nav {
    gap: 20px;
  }
  .wordmark-sub {
    display: none;
  }

  .tool-workspace {
    grid-template-columns: minmax(0, 1fr) 280px;
    gap: 20px;
  }
  .site-footer {
    margin: 0 24px;
  }
}
@media (max-width: 767px) {
  .site-nav {
    padding: 14px 20px;
    gap: 14px;
    flex-wrap: wrap;
    min-height: 70px;
  }
  .brand-symbol {
    width: 28px;
    height: 28px;
    font-size: 19px;
  }
  .primary-nav a {
    padding: 7px 10px;
  }
  .nav-actions {
    gap: 10px;
  }
  .nav-actions:has(input) {
    width: 100%;
  }
  .site-main {
    padding: 32px 20px 56px;
  }

