  .trending-card {
    padding: 14px;
  }
  .trending-card > div:last-child {
    flex-wrap: wrap;
    gap: 8px;
  }
  .trending-card > div:last-child > div {
    flex-wrap: wrap;
  }
  .tool-workspace {
    display: flex;
