  .stats-page > .metric-grid > .bg-dark-800:nth-child(3) {
    border-left: 0;
    padding-left: 0;
  }
  .stats-page .metric-grid .text-3xl {
    font-size: 29px;
  }
  .stats-page > .grid > .bg-dark-800,
  .stats-page > .bg-dark-800,
  .audience-panel > .bg-dark-800 {
    padding: 18px;
  }
  .site-footer {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }
}
