    {forecast && <span class="download-milestone">On pace for <strong>{formatCompact(forecast.target)} {unit}</strong><br/>{dateLabel(forecast.hitDate)} · {formatForecastRelative(forecast.daysAway)}</span>}
  </div>
  <svg viewBox="0 0 540 218" role="img" aria-label={`${title} and 7-day average. Latest average ${latest.value===null?'unavailable':Math.round(latest.value).toLocaleString()}. ${forecast ? `Projected to reach ${forecast.target.toLocaleString()} ${unit} on ${dateLabel(forecast.hitDate)}.`:''}`}>
    {[0,.5,1].map(f=><g><line x1="48" x2="512" y1={y(max*f)} y2={y(max*f)} stroke="var(--border)" stroke-dasharray="3 5"/><text x="40" y={y(max*f)+4} text-anchor="end">{formatCompact(max*f)}</text></g>)}
    {data.filter(p=>p.value!==null).map(p=><rect x={x(p.date)-width/2} y={y(p.value!)} width={width} height={186-y(p.value!)} fill="var(--accent)" opacity=".4"><title>{p.date}: {p.value!.toLocaleString()} {unit}</title></rect>)}
