        items[next]?.focus();
      }
    }
  }}>
    <button type="button" ref={trigger} class="site-menu-trigger" aria-label="More resources and account" aria-expanded={open} aria-controls="site-menu-panel" onClick={() => setOpen(value => !value)}>
